// KSDD Books 360 — Vyapar replacement UI (vanilla JS, CSP-safe).
(function(){
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], app=$('#app'), modal=$('#sr-modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const R=(p,dec=0)=>(p<0?'−':'')+'₹'+(Math.abs(p||0)/100).toLocaleString('en-IN',{minimumFractionDigits:dec,maximumFractionDigits:dec});
const R2=p=>R(p,2), rup=p=>((p||0)/100).toFixed(2).replace(/\.00$/,''), qn=v=>Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:3});
const MON=m=>new Date(m+'-01T00:00:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'}), DT=d=>d?d.slice(8,10)+'/'+d.slice(5,7)+'/'+d.slice(0,4):'';
const lastDay=m=>m+'-'+String(new Date(+m.slice(0,4),+m.slice(5,7),0).getDate()).padStart(2,'0');
const S={boot:null,tab:'dash',month:null,lists:null,acct:'Cash',tf:'all',q:'',kind:'supplier',sq:'',imp:null,party:null};
function toast(m,e=false){ const t=$('#sr-toast'); t.textContent=m; t.className=e?'e':''; t.style.display='block'; clearTimeout(toast.t); toast.t=setTimeout(()=>t.style.display='none',e?6000:3200); }
async function api(r,body,qs=''){ const res=await fetch('books-api.php?r='+r+qs,body===undefined?{credentials:'same-origin'}:{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':S.boot?.csrf||''},body:JSON.stringify(body)});
  let j; try{ j=await res.json(); }catch{ throw Error('Server returned an unexpected response.'); } if(res.status===401){ app.innerHTML=`<div class="wrap"><div class="card"><div class="card-b empty"><h2>Please sign in</h2><p style="margin:10px 0 18px">Sign in to the KSDD CRM first.</p><a href="index.php"><button class="pri">Go to sign in →</button></a></div></div></div>`; throw Error('Please sign in'); } if(!res.ok) throw Error(j.error||'Request failed'); return j; }
function openModal(title,body,wide=false){ $('#sr-modal-body').innerHTML=`<div class="md"><div class="md-h"><h2>${title}</h2><button type="button" data-a="close" aria-label="Close">×</button></div>${body}<div class="err-box" id="md-err"></div></div>`; modal.style.maxWidth=wide?'min(1100px,96vw)':''; if(!modal.open) modal.showModal(); }
const mErr=m=>{ const e=$('#md-err'); if(e) e.textContent=m||''; }; const owner=()=>!!S.boot?.user?.owner;
const TY=k=>S.boot.types[k]||{label:k,dir:'in'}; const badge=t=>`<span class="tbadge ${t==='cash_access'?'ca':TY(t).dir}">${esc(TY(t).label)}</span>`;
const sev=s=>`<span class="sev ${s}">${s}</span>`;

/* ---------- boot ---------- */
async function boot(){ try{ S.boot=await api('boot'); }catch(e){ if(!/sign in/.test(e.message)) app.innerHTML=`<div class="wrap"><div class="note w">${esc(e.message)}</div></div>`; return; }
  if(!S.boot.installed){ app.innerHTML=`${top(false)}<div class="wrap"><div class="card"><div class="card-b" style="max-width:640px"><h1>Set up Books</h1><p class="mut" style="margin:10px 0 16px;line-height:1.7">Adds the dd_bk_* tables (cash book, parties, items, stock, month lock). The CRM daybook and all existing data stay unchanged. Recommended: use <a href="upgrade.php">Database upgrade</a>, which installs every module at once.</p>${owner()?`<button class="pri" data-a="setup">Set up Books</button> <a href="upgrade.php"><button class="out">Open Database upgrade</button></a>`:'<div class="note w">Ask the owner to open this page once.</div>'}</div></div></div>`; return; }
  const h=new URLSearchParams(location.hash.slice(1)); S.month=h.get('m')||S.boot.months[0]?.month||S.boot.today.slice(0,7); S.tab=h.get('t')||(S.boot.months.length?'dash':'imp'); if(!TABS.some(t=>t[0]===S.tab)) S.tab='dash'; await loadLists(); render(); }
async function loadLists(){ S.lists=await api('lists'); }
function top(full=true){ const ms=S.boot?.months||[]; const opts=[...new Set([S.boot?.today?.slice(0,7),...ms.map(m=>m.month)].filter(Boolean))].sort().reverse();
  return `<header class="top"><div class="brand"><i>₹</i><div><b>Books</b><small>KHADAK SINGH DA DHABA</small></div></div>${full?`<select id="month-pick" aria-label="Month">${opts.map(m=>`<option value="${m}" ${m===S.month?'selected':''}>${MON(m)}${ms.find(x=>x.month===m)?.status==='locked'?' 🔒':''}</option>`).join('')}</select>`:''}<div class="sp"></div>${full?`<button class="pri" data-a="new">＋ New entry</button>`:''}<a href="salary.php">Salary</a><a href="index.php">CRM</a>${owner()?'<a href="upgrade.php">DB upgrade</a>':''}</header>`; }
const TABS=[['dash','Dashboard'],['day','Daybook'],['pur','Purchases'],['exp','Expenses'],['par','Parties & dues'],['stk','Stock'],['aud','Audit checks'],['imp','Import Vyapar'],['set','Settings']];
function render(){ history.replaceState(null,'','#m='+S.month+'&t='+S.tab); app.innerHTML=top()+`<nav class="tabs">${TABS.filter(t=>t[0]!=='set'||owner()).map(([k,l])=>`<button data-tab="${k}" class="${S.tab===k?'on':''}">${l}</button>`).join('')}</nav><main class="wrap" id="main"><div class="empty">Loading…</div></main>`;
  ({dash,day,pur,exp,par,stk,aud,imp,set})[S.tab]().catch(e=>{ $('#main').innerHTML=`<div class="note w">${esc(e.message)}</div>`; }); }
const kpi=(l,v,cls='',em='')=>`<div class="kpi ${cls}"><small>${l}</small><b>${v}</b>${em?`<em>${em}</em>`:''}</div>`;

/* ---------- dashboard ---------- */
async function dash(){ const [s,a,p]=await Promise.all([api('month',undefined,'&m='+S.month),api('audit',undefined,'&m='+S.month),api('parties')]); const P=s.pl, by=s.by_type;
  const dues=p.parties.filter(x=>x.kind==='supplier'&&x.payable>0).sort((x,y)=>y.payable-x.payable); const recv=p.parties.filter(x=>x.receivable>0);
  const mx=Math.max(1,...s.daily.map(d=>Math.max(d.sale,d.expense+d.purchase))); const hi=a.issues.filter(i=>i.sev==='high').length;
  const locked=s.status==='locked';
  $('#main').innerHTML=`<div class="card-h" style="padding:0 0 12px;border:0"><div><h1>${MON(S.month)}</h1><p class="mut sm-t">${(by.sale?.n||0)} sale entries · ${(by.expense?.n||0)} expenses · ${(by.purchase?.n||0)} purchases · ${locked?'🔒 locked':'open'}</p></div><div class="bar" style="margin:0"><button class="out" data-a="exp-csv">⬇ Expense CSV</button>${S.boot.user.close?(locked?(owner()?'<button class="out" data-a="unlock">Unlock month</button>':''):'<button class="pri" data-a="lock">🔒 Count cash & lock month</button>'):''}</div></div>
  <div class="kpis">${kpi('Sales',R(P.sales),'grn',(by.sale?.n||0)+' entries')}${kpi('Cash Acess',R(P.not_in_pl.cash_access),'','not a sale')}${kpi('Purchases',R(P.purchases),'amb',P.food_cost_pct!=null?P.food_cost_pct+'% of sales':'')}${kpi('Staff cost',R(P.staff_cost),'',P.staff_cost_source)}${kpi('Other expenses',R(P.other_expenses))}${kpi('Profit (as recorded)',R(P.profit),P.profit<0?'red':'grn','before tax/depreciation')}${kpi('Cash in hand',R(s.cash.closing),s.cash.closing<0?'red':'','opening '+R(s.cash.opening))}${kpi('Supplier dues',R(dues.reduce((x,y)=>x+y.payable,0)),'red',dues.length+' suppliers')}${kpi('Audit issues',hi+' high','red',a.issues.length+' total')}</div>
  ${P.profit<0||P.food_cost_pct>45?`<div class="note w">These numbers come straight from the entries. They will only be reliable after the audit problems are fixed (missing daily sales, purchases with no value, old dues booked as expense, stock never counted). Food cost for a dhaba is usually 30–40% of sales.</div>`:''}
  <div class="grid2"><div class="card"><div class="card-h"><h2>Daily sales vs spend</h2><span class="mut sm-t"><span style="display:inline-block;width:10px;height:10px;background:var(--g2)"></span> sale <span style="display:inline-block;width:10px;height:10px;background:#e9a35a"></span> purchase+expense</span></div><div class="card-b"><div class="dbars">${s.daily.map(d=>`<div title="${DT(d.date)} sale ${R(d.sale)} · spend ${R(d.expense+d.purchase)}"><span class="s" style="height:${d.sale/mx*120}px"></span><span class="e" style="height:${(d.expense+d.purchase)/mx*120}px"></span></div>`).join('')||'<p class="mut">No entries this month.</p>'}</div></div></div>
  <div class="card"><div class="card-h"><h2>Suggestions for this month</h2><button class="sm out" data-tab="aud">All checks</button></div><ul class="sug">${a.issues.slice(0,7).map(i=>`<li>${sev(i.sev)} <b style="display:inline">${esc(i.cat)}</b> — ${esc(i.text)}${i.fix?`<br><em>→ ${esc(i.fix)}</em>`:''}</li>`).join('')||'<li>Nothing to fix 👍</li>'}</ul></div></div>
  <div class="grid2"><div class="card"><div class="card-h"><h2>Expenses by group</h2></div><div class="tw"><table><tbody>${Object.entries(s.expense_groups).map(([g,v])=>`<tr><td>${esc(g)}${/not expense/.test(g)?' <span class="st grey">excluded</span>':''}</td><td class="n">${R(v)}</td></tr>`).join('')||'<tr><td class="empty">No expenses</td></tr>'}</tbody></table></div></div>
  <div class="card"><div class="card-h"><h2>Accounts</h2></div><div class="tw"><table><thead><tr><th>Account</th><th class="n">Opening</th><th class="n">Closing</th></tr></thead><tbody>${s.accounts.filter(x=>x.opening||x.closing||x.account==='Cash').map(x=>`<tr><td>${esc(x.account)}</td><td class="n">${R(x.opening)}</td><td class="n ${x.closing<0?'neg':''}">${R(x.closing)}</td></tr>`).join('')}</tbody></table></div><div class="card-b sm-t mut">Bank balances only show transfers/payments entered here — match them with the bank statement.</div></div>
  <div class="card"><div class="card-h"><h2>Staff money check</h2></div><div class="card-b calc"><div><span>Staff expenses in Books</span><b>${R(s.staff_recon.books_staff_expense)}</b></div><div><span>Payments to staff parties in Books</span><b>${R(s.staff_recon.books_staff_payments)}</b></div>${s.staff_recon.register?`<div class="t"><span>Salary Register: earned</span><b>${R(s.staff_recon.register.earned)}</b></div><div><span>Register: advances + payments dated this month</span><b>${R(s.staff_recon.register.cash_out_in_month)}</b></div>`:'<div class="t"><span>Salary Register</span><b>no sheet for this month</b></div>'}</div></div>
  <div class="card"><div class="card-h"><h2>Top supplier dues</h2><button class="sm out" data-tab="par">All parties</button></div><div class="tw"><table><tbody>${dues.slice(0,8).map(x=>`<tr><td><button class="link" data-a="stmt" data-id="${x.id}">${esc(x.name)}</button><br><small class="mut">${x.last_paid?'last paid '+DT(x.last_paid):'never paid'}</small></td><td class="n"><b>${R(x.payable)}</b></td><td><button class="sm pri" data-a="pay-party" data-id="${x.id}">Pay</button></td></tr>`).join('')||'<tr><td class="empty">No dues</td></tr>'}${recv.length?`<tr class="tot"><td>Customers owe us</td><td class="n">${R(recv.reduce((x,y)=>x+y.receivable,0))}</td><td></td></tr>`:''}</tbody></table></div></div></div>`; }

/* ---------- daybook ---------- */
async function day(){ const f=S.from||S.month+'-01', t=S.to||lastDay(S.month); const d=await api('daybook',undefined,`&from=${f}&to=${t}&account=${encodeURIComponent(S.acct)}`); const q=S.q.toLowerCase();
  const vis=d.txns.filter(x=>(S.tf==='all'||x.type===S.tf)&&(!q||[x.party,x.category,x.description,x.bill_no].join(' ').toLowerCase().includes(q)));
  const byDay={}; vis.forEach(x=>(byDay[x.date]??=[]).push(x)); const dayInfo=Object.fromEntries(d.days.map(x=>[x.date,x]));
  $('#main').innerHTML=`<div class="bar"><label class="f" style="flex-direction:row;align-items:center;gap:6px">From <input type="date" id="d-from" value="${f}"></label><label class="f" style="flex-direction:row;align-items:center;gap:6px">To <input type="date" id="d-to" value="${t}"></label><select id="d-acct" class="chip">${S.boot.accounts.map(a=>`<option ${a===S.acct?'selected':''}>${esc(a)}</option>`).join('')}</select><select id="d-type" class="chip"><option value="all">All types</option>${Object.entries(S.boot.types).map(([k,v])=>`<option value="${k}" ${S.tf===k?'selected':''}>${esc(v.label)}</option>`).join('')}</select><input type="search" id="d-q" placeholder="Search party, category, note…" value="${esc(S.q)}"><span class="sp"></span><button class="out" data-a="day-csv">⬇ CSV</button></div>
  <div class="kpis">${kpi('Opening '+esc(S.acct),R(d.opening))}${kpi('In',R(d.days.reduce((a,x)=>a+x.in,0)),'grn')}${kpi('Out',R(d.days.reduce((a,x)=>a+x.out,0)),'red')}${kpi('Closing '+esc(S.acct),R(d.closing),d.closing<0?'red':'')}</div>
  <div class="card"><div class="tw" style="max-height:70vh"><table><thead><tr><th>Type</th><th>Party / category</th><th>Note</th><th class="n">Bill total</th><th class="n">Paid</th><th class="n">${esc(S.acct)} in/out</th><th class="n">Running</th><th></th></tr></thead><tbody>${Object.keys(byDay).sort().map(dt=>{const di=dayInfo[dt]||{}; return `<tr class="day"><td colspan="3">${DT(dt)} · ${new Date(dt+'T00:00:00').toLocaleDateString('en-IN',{weekday:'short'})}</td><td class="n" colspan="2">sale ${R(di.sale||0)}</td><td class="n">+${R(di.in||0)} / −${R(di.out||0)}</td><td class="n ${di.close<0?'neg':''}">${R(di.close??0)}</td><td></td></tr>`+byDay[dt].map(x=>`<tr class="${x.voided?'void':''}"><td>${badge(x.type)}</td><td>${esc(x.party||'')}${x.category?`<br><small class="mut">${esc(x.category)}</small>`:''}${x.type==='transfer'?`<br><small class="mut">${esc(x.account)} → ${esc(x.to_account)}</small>`:x.account!=='Cash'?`<br><small class="mut">${esc(x.account)}</small>`:''}</td><td class="mut sm-t" style="white-space:normal;max-width:280px">${esc(x.description||'')}${x.lines.length?` <span class="st grey">${x.lines.length} items</span>`:''}${x.voided?' (cancelled: '+esc(x.void_reason)+')':''}</td><td class="n">${R(x.total)}</td><td class="n">${x.paid!==x.total?R(x.paid):''}</td><td class="n ${x.cash<0?'neg':x.cash>0?'pos':'mut'}">${x.cash?R(x.cash):'—'}</td><td class="n mut">${R(x.running)}</td><td>${x.voided?'':`<button class="sm out" data-a="edit" data-id="${x.id}">Open</button>`}</td></tr>`).join('')}).join('')||'<tr><td colspan="8" class="empty">No entries</td></tr>'}</tbody></table></div></div>`; }

/* ---------- purchases & expenses ---------- */
async function pur(){ const d=await api('daybook',undefined,`&from=${S.month}-01&to=${lastDay(S.month)}&account=Cash`); const ps=d.txns.filter(x=>x.type==='purchase'&&!x.voided); const q=S.pq||'';
  const sup={}; ps.forEach(x=>{ const s=(sup[x.party]??={n:0,total:0,paid:0}); s.n++; s.total+=x.total; s.paid+=x.paid; });
  const vis=ps.filter(x=>!q||x.party===q);
  $('#main').innerHTML=`<div class="bar"><select id="p-sup" class="chip"><option value="">All suppliers (${ps.length} bills)</option>${Object.keys(sup).sort().map(k=>`<option ${k===q?'selected':''} value="${esc(k)}">${esc(k)} (${sup[k].n})</option>`).join('')}</select><span class="sp"></span><button class="pri" data-a="new" data-type="purchase">＋ Purchase bill</button></div>
  <div class="kpis">${kpi('Purchases',R(ps.reduce((a,x)=>a+x.total,0)))}${kpi('Paid at bill',R(ps.reduce((a,x)=>a+x.paid,0)))}${kpi('On credit',R(ps.reduce((a,x)=>a+x.total-x.paid,0)),'amb')}${kpi('Bills without items',ps.filter(x=>!x.lines.length).length,'red')}</div>
  <div class="card"><div class="tw"><table><thead><tr><th>Date</th><th>Supplier</th><th>Bill no</th><th>Items</th><th class="n">Total</th><th class="n">Paid</th><th class="n">Credit</th><th></th></tr></thead><tbody>${vis.map(x=>`<tr><td>${DT(x.date)}</td><td>${esc(x.party)}</td><td>${esc(x.bill_no||'')}</td><td class="sm-t" style="white-space:normal;max-width:380px">${x.lines.length?x.lines.slice(0,4).map(l=>`${esc(l.item)} ${qn(l.qty)} ${esc(l.unit||'')} @ ${R2(l.rate)}${l.discount?` −${R(l.discount)} disc`:''}`).join(', ')+(x.lines.length>4?` +${x.lines.length-4} more`:''):'<span class="st Overpaid">no items</span>'}</td><td class="n">${R(x.total)}</td><td class="n">${R(x.paid)}</td><td class="n">${R(x.total-x.paid)}</td><td><button class="sm out" data-a="edit" data-id="${x.id}">Open</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No purchases this month</td></tr>'}</tbody></table></div></div>`; }
async function exp(){ const [s,d]=await Promise.all([api('month',undefined,'&m='+S.month),api('daybook',undefined,`&from=${S.month}-01&to=${lastDay(S.month)}&account=Cash`)]); const es=d.txns.filter(x=>x.type==='expense'&&!x.voided); const c=S.ec||'';
  $('#main').innerHTML=`<div class="bar"><span class="mut">Click a category to see its entries.</span><span class="sp"></span><button class="out" data-a="exp-csv">⬇ CSV</button><button class="pri" data-a="new" data-type="expense">＋ Expense</button></div><div class="grid2"><div class="card"><div class="card-h"><h2>${MON(S.month)} by category</h2><b>${R(es.reduce((a,x)=>a+x.total,0))}</b></div><div class="tw"><table><thead><tr><th>Category</th><th>Group</th><th class="n">Entries</th><th class="n">Amount</th></tr></thead><tbody>${s.expense_categories.map(x=>`<tr class="${x.category===c?'hl':''}"><td><button class="link" data-a="ecat" data-c="${esc(x.category)}">${esc(x.category)}</button></td><td class="sm-t">${esc(x.group)}</td><td class="n">${x.n}</td><td class="n">${R(x.amount)}</td></tr>`).join('')}</tbody></table></div></div>
  <div class="card"><div class="card-h"><h2>${c?esc(c):'Latest expenses'}</h2>${c?'<button class="sm out" data-a="ecat" data-c="">Show all</button>':''}</div><div class="tw" style="max-height:65vh"><table><tbody>${es.filter(x=>!c||x.category===c||(c==='(none)'&&!x.category)).slice(-200).reverse().map(x=>`<tr><td>${DT(x.date)}</td><td>${esc(x.party||'')}<br><small class="mut">${esc(x.category||'')} · ${esc(x.account)}</small></td><td class="n">${R(x.total)}${x.paid<x.total?`<br><small class="neg">unpaid ${R(x.total-x.paid)}</small>`:''}</td><td><button class="sm out" data-a="edit" data-id="${x.id}">Open</button></td></tr>`).join('')}</tbody></table></div></div></div>`; }

/* ---------- parties ---------- */
async function par(){ const p=(await api('parties')).parties; S.parties=p; const q=S.sq.toLowerCase(); const vis=p.filter(x=>(S.kind==='all'||x.kind===S.kind)&&(!q||(x.name+' '+(x.aliases||'')).toLowerCase().includes(q)));
  const cnt=k=>p.filter(x=>k==='all'||x.kind===k).length;
  $('#main').innerHTML=`<div class="bar"><input type="search" id="p-q" placeholder="Search party…" value="${esc(S.sq)}">${['supplier','customer','staff','other','all'].map(k=>`<button class="chip ${S.kind===k?'on':''}" data-kind="${k}">${k[0].toUpperCase()+k.slice(1)} (${cnt(k)})</button>`).join('')}<span class="sp"></span><button class="out" data-a="parties-csv">⬇ CSV</button><button class="out" data-a="merge-party">Merge duplicates</button><button class="pri" data-a="party-edit" data-id="0">＋ Party</button></div>
  <div class="kpis">${kpi('We owe suppliers',R(p.filter(x=>x.kind==='supplier'&&x.payable>0).reduce((a,x)=>a+x.payable,0)),'red')}${kpi('Customers owe us',R(p.filter(x=>x.receivable>0).reduce((a,x)=>a+x.receivable,0)),'grn')}${kpi('Staff paid via Books',R(p.filter(x=>x.kind==='staff').reduce((a,x)=>a+x.paid_out,0)),'','use Salary Register instead')}</div>
  <div class="card"><div class="tw" style="max-height:70vh"><table><thead><tr><th>Party</th><th>Type</th><th class="n">Opening</th><th class="n">Purchases</th><th class="n">Paid</th><th class="n">Sales</th><th class="n">Received</th><th class="n">Balance</th><th>Last paid</th><th></th></tr></thead><tbody>${vis.map(x=>`<tr><td><button class="link" data-a="stmt" data-id="${x.id}">${esc(x.name)}</button>${x.aliases?`<br><small class="mut">also: ${esc(x.aliases)}</small>`:''}</td><td>${x.kind}</td><td class="n">${x.opening?R(x.opening):'—'}</td><td class="n">${R(x.purchases)}</td><td class="n">${R(x.paid_out+x.paid_with_bill)}</td><td class="n">${x.sales?R(x.sales):'—'}</td><td class="n">${x.paid_in?R(x.paid_in):'—'}</td><td class="n"><b class="${x.balance>0?'neg':x.balance<0?'pos':''}">${x.balance>0?'We owe '+R(x.balance):x.balance<0?'Owes us '+R(-x.balance):'—'}</b></td><td class="sm-t">${x.last_paid?DT(x.last_paid):'—'}</td><td>${x.payable>0?`<button class="sm pri" data-a="pay-party" data-id="${x.id}">Pay</button> `:''}${x.receivable>0?`<button class="sm pri" data-a="recv-party" data-id="${x.id}">Receive</button> `:''}<button class="sm out" data-a="party-edit" data-id="${x.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="10" class="empty">None</td></tr>'}</tbody></table></div></div>`; }
async function stmt(id){ const s=await api('party',undefined,`&id=${id}`); const p=s.party;
  openModal(esc(p.name)+' · statement',`<div class="kpis">${kpi('Purchases',R(p.purchases))}${kpi('Paid',R(p.paid_out+p.paid_with_bill))}${kpi('Balance',p.balance>=0?'We owe '+R(p.balance):'Owes us '+R(-p.balance),p.balance>0?'red':'grn')}</div><p class="mut sm-t">Opening balance ${R(p.opening)} ${p.opening?'':'— not entered. Ask the supplier for their balance on your start date and enter it (Edit party).'}</p><div class="tw" style="max-height:55vh"><table><thead><tr><th>Date</th><th>Type</th><th>Detail</th><th class="n">Bill</th><th class="n">Paid</th><th class="n">Effect</th><th class="n">Balance</th></tr></thead><tbody>${s.txns.map(t=>`<tr><td>${DT(t.date)}</td><td>${badge(t.type)}</td><td class="sm-t">${esc(t.bill_no||t.category||'')} ${t.lines.length?t.lines.length+' items':''}</td><td class="n">${R(t.total)}</td><td class="n">${R(t.paid)}</td><td class="n">${R(t.effect)}</td><td class="n"><b>${R(t.balance)}</b></td></tr>`).join('')}</tbody></table></div><div class="acts">${p.payable>0?`<button class="pri" data-a="pay-party" data-id="${p.id}">Pay ${esc(p.name)}</button>`:''}</div>`,true); }
function partyEdit(id){ const x=(S.parties||[]).find(p=>p.id===id)||{kind:'supplier',opening:0,credit_days:0};
  openModal(id?'Edit party':'New party',`<form data-form="party" data-id="${id}"><div class="fg"><label class="f">Name *<input name="name" value="${esc(x.name||'')}" required></label><label class="f">Type<select name="kind">${['supplier','customer','staff','other'].map(k=>`<option ${k===x.kind?'selected':''}>${k}</option>`).join('')}</select></label><label class="f">Phone<input name="phone" value="${esc(x.phone||'')}"></label><label class="f">GSTIN<input name="gstin" value="${esc(x.gstin||'')}"></label><label class="f">Opening balance ₹ (+ we owe, − they owe)<input name="opening" value="${rup(x.opening)}"></label><label class="f">Credit days<input name="credit_days" value="${x.credit_days||0}" inputmode="numeric"></label></div><label class="f">Other spellings (comma separated)<input name="aliases" value="${esc(x.aliases||'')}"></label><label class="f" style="margin-top:8px">Note<input name="note" value="${esc(x.note||'')}"></label><label class="ck"><input type="checkbox" name="inactive" value="1" ${x.active===0?'checked':''}> Inactive</label><div class="acts"><button class="pri">Save</button></div></form>`); }

/* ---------- stock ---------- */
async function stk(){ const it=(await api('stock')).items; S.items=it; const q=(S.iq||'').toLowerCase(); const f=S.if||'stock';
  const vis=it.filter(x=>(!q||(x.name+' '+(x.category||'')).toLowerCase().includes(q))&&(f==='all'||(f==='stock'&&x.is_stock)||(f==='low'&&x.is_stock&&x.reorder>0&&x.closing<=x.reorder)||(f==='neg'&&x.closing<0)||(f==='unused'&&x.is_stock&&x.in>0&&!x.used&&!x.sold&&!x.adjust)||(f==='var'&&x.min_rate&&x.max_rate>1.5*x.min_rate)));
  const cnt=k=>it.filter(x=>(k==='all')||(k==='stock'&&x.is_stock)||(k==='low'&&x.is_stock&&x.reorder>0&&x.closing<=x.reorder)||(k==='neg'&&x.closing<0)||(k==='unused'&&x.is_stock&&x.in>0&&!x.used&&!x.sold&&!x.adjust)||(k==='var'&&x.min_rate&&x.max_rate>1.5*x.min_rate)).length;
  $('#main').innerHTML=`<div class="bar"><input type="search" id="i-q" placeholder="Search item…" value="${esc(S.iq||'')}">${[['stock','Stock items'],['low','Low stock'],['neg','Negative'],['unused','Never used'],['var','Rate jumps'],['all','All']].map(([k,l])=>`<button class="chip ${f===k?'on':''}" data-if="${k}">${l} (${cnt(k)})</button>`).join('')}<span class="sp"></span><button class="out" data-a="stock-csv">⬇ CSV</button><button class="out" data-a="merge-item">Merge items</button><button class="out" data-a="move" data-k="count">Stock count</button><button class="pri" data-a="move" data-k="consume">Kitchen usage</button></div>
  <div class="kpis">${kpi('Stock value (last rate)',R(it.reduce((a,x)=>a+(x.is_stock?x.value:0),0)))}${kpi('Items',it.filter(x=>x.is_stock).length)}${kpi('Never issued/counted',cnt('unused'),'red','closing not reliable')}${kpi('Low stock',cnt('low'),'amb')}</div>
  <div class="card"><div class="tw" style="max-height:70vh"><table><thead><tr><th>Item</th><th>Unit</th><th class="n">Opening</th><th class="n">In</th><th class="n">Sold</th><th class="n">Used</th><th class="n">Adjust</th><th class="n">Closing</th><th class="n">Last rate</th><th class="n">Min–max</th><th class="n">Value</th><th></th></tr></thead><tbody>${vis.map(x=>`<tr><td><button class="link" data-a="item" data-id="${x.id}">${esc(x.name)}</button><br><small class="mut">${esc(x.category||'')}${x.is_stock?'':' · menu/non-stock'}</small></td><td>${esc(x.unit||'')}</td><td class="n">${qn(x.opening)}</td><td class="n">${qn(x.in)}</td><td class="n">${qn(x.sold)}</td><td class="n">${qn(x.used)}</td><td class="n">${qn(x.adjust)}</td><td class="n"><b class="${x.closing<0?'neg':x.reorder&&x.closing<=x.reorder?'neg':''}">${qn(x.closing)}</b></td><td class="n">${x.last_rate!=null?R2(x.last_rate):'—'}</td><td class="n sm-t ${x.min_rate&&x.max_rate>1.5*x.min_rate?'neg':''}">${x.min_rate!=null?R2(x.min_rate)+'–'+R2(x.max_rate):''}</td><td class="n">${R(x.value)}</td><td><button class="sm out" data-a="item-edit" data-id="${x.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="12" class="empty">No items</td></tr>'}</tbody></table></div></div>`; }
function moveDialog(kind){ const items=(S.items||[]).filter(x=>x.is_stock&&x.active); const L={consume:'Kitchen usage / issue',wastage:'Wastage',count:'Physical stock count',adjust:'Adjustment (+/−)',opening:'Opening stock'};
  openModal(L[kind],`<form data-form="move"><div class="fg"><label class="f">Type<select name="kind">${Object.entries(L).map(([k,l])=>`<option value="${k}" ${k===kind?'selected':''}>${l}</option>`).join('')}</select></label><label class="f">Date<input type="date" name="date" value="${S.boot.today}"></label><label class="f">Note<input name="note"></label></div><p class="mut sm-t">${kind==='count'?'Type what you actually counted — the difference is posted automatically.':'Enter quantities only for items that moved. Leave others blank.'}</p><input type="search" id="mv-q" placeholder="Filter items…" style="width:100%;padding:8px;border:1px solid var(--line);border-radius:8px;margin:6px 0"><div class="tw" style="max-height:50vh"><table><thead><tr><th>Item</th><th class="n">Book stock</th><th>Qty</th></tr></thead><tbody>${items.map(x=>`<tr data-mv="${esc(x.name.toLowerCase())}"><td>${esc(x.name)} <small class="mut">${esc(x.unit||'')}</small></td><td class="n">${qn(x.closing)}</td><td><input name="q_${x.id}" inputmode="decimal" style="width:90px;padding:6px;border:1px solid var(--line);border-radius:6px"></td></tr>`).join('')}</tbody></table></div><div class="acts"><button class="pri">Save</button></div></form>`,true); }
async function itemCard(id){ const c=await api('item',undefined,'&id='+id); const it=c.item;
  openModal(esc(it.name),`<p class="mut sm-t">${esc(it.category||'')} · unit ${esc(it.unit||'—')} · ${it.is_stock==1?'stock item':'menu / non-stock'}${it.std_rate?' · standard rate '+R2(+it.std_rate):''}</p><h3 style="margin:10px 0 6px">Purchases & sales</h3><div class="tw" style="max-height:38vh"><table><thead><tr><th>Date</th><th>Type</th><th>Party</th><th class="n">Qty</th><th class="n">Rate</th><th class="n">Amount</th></tr></thead><tbody>${c.lines.map(l=>`<tr><td>${DT(l.date)}</td><td>${badge(l.type)}</td><td>${esc(l.party||'')}</td><td class="n">${qn(l.qty)} ${esc(l.unit||'')}</td><td class="n ${it.std_rate&&+l.rate>1.1*it.std_rate?'neg':''}">${R2(+l.rate)}</td><td class="n">${R(+l.amount)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">None</td></tr>'}</tbody></table></div><h3 style="margin:12px 0 6px">Usage / counts</h3><div class="tw" style="max-height:25vh"><table><tbody>${c.moves.map(m=>`<tr><td>${DT(m.date)}</td><td>${esc(m.kind)}</td><td class="n">${qn(m.qty)}</td><td class="sm-t mut">${esc(m.note||'')}</td></tr>`).join('')||'<tr><td class="empty">No usage recorded</td></tr>'}</tbody></table></div>`,true); }
function itemEdit(id){ const x=(S.items||[]).find(i=>i.id===id)||{is_stock:1,active:1};
  openModal(id?'Edit item':'New item',`<form data-form="item" data-id="${id}"><div class="fg"><label class="f">Name *<input name="name" value="${esc(x.name||'')}" required></label><label class="f">Unit<input name="unit" value="${esc(x.unit||'')}" placeholder="Kg, Pcs, Ctn…"></label><label class="f">Category<input name="category" value="${esc(x.category||'')}"></label><label class="f">Re-order level<input name="reorder" value="${x.reorder||0}"></label><label class="f">Opening stock<input name="opening_qty" value="${x.opening!=null?x.opening-0:0}"></label><label class="f">Standard rate ₹<input name="std_rate" value="${x.std_rate!=null?rup(x.std_rate):''}"></label></div><label class="ck"><input type="checkbox" name="is_stock" value="1" ${x.is_stock?'checked':''}> Track stock (untick for menu items like Aloo Paratha)</label><label class="ck"><input type="checkbox" name="inactive" value="1" ${x.active===0?'checked':''}> Inactive</label><div class="acts"><button class="pri">Save</button></div></form>`); }
function mergeDialog(kind){ const list=kind==='party'?(S.parties||[]):(S.items||[]); const o=list.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');
  openModal(kind==='party'?'Merge duplicate parties':'Merge duplicate items',`<form data-form="merge" data-kind="${kind}"><p class="mut sm-t">All entries of the first are moved to the second, and the first is deleted. Its name is kept as an "other spelling".</p><div class="fg"><label class="f">Duplicate (remove)<select name="from">${o}</select></label><label class="f">Keep<select name="into">${o}</select></label></div><div class="acts"><button class="dan">Merge</button></div></form>`); }

/* ---------- audit ---------- */
async function aud(){ const all=S.aall; const a=await api('audit',undefined,all?'':'&m='+S.month); const sv=S.asv||'all';
  const list=a.issues.filter(i=>sv==='all'||i.sev===sv); const c=k=>a.issues.filter(i=>k==='all'||i.sev===k).length;
  $('#main').innerHTML=`<div class="note">Live checks on your books. They update as soon as you fix entries. ${all?'Showing <b>all months</b>.':'Showing <b>'+MON(S.month)+'</b>.'} <button class="link" data-a="aall">${all?'Show this month only':'Check all months'}</button></div><div class="bar">${['high','medium','low','all'].map(s=>`<button class="chip ${sv===s?'on':''}" data-asv="${s}">${s[0].toUpperCase()+s.slice(1)} (${c(s)})</button>`).join('')}</div>
  <div class="card"><ul class="iss">${list.map(i=>`<li>${sev(i.sev)}<div style="flex:1"><b>${esc(i.cat)}</b>${i.amount?` <span class="mut sm-t">${R(i.amount)}</span>`:''}<br>${esc(i.text)}${i.fix?`<br><em class="sm-t" style="color:var(--g2);font-style:normal">→ ${esc(i.fix)}</em>`:''}${i.list&&i.list.length?`<details class="more"><summary>Show ${i.list.length} entries</summary><ul>${i.list.map(x=>`<li>${x.date?DT(x.date)+' · ':''}${esc(x.text)} ${x.txn?`<button class="link sm-t" data-a="edit" data-id="${x.txn}">open</button>`:''}</li>`).join('')}</ul></details>`:''}</div>${i.txn?`<button class="sm out" data-a="edit" data-id="${i.txn}">Open</button>`:''}${i.cat==='Unexplained adjustment'&&i.list&&i.list.length?`<button class="sm pri" data-a="reclass" data-from="add_cash" data-ids="${i.list.filter(x=>x.txn&&(x.amount||0)<5000000).map(x=>x.txn).join(',')}">Convert daily ones to Cash Acess</button>`:''}${i.cat==='Cash Acess booked as sale'&&i.list?`<button class="sm pri" data-a="reclass" data-from="sale" data-ids="${i.list.map(x=>x.txn).join(',')}">Change all to Cash Acess</button>`:''}</li>`).join('')||'<li class="empty">Nothing to fix 👍</li>'}</ul></div>`; }

/* ---------- import ---------- */
async function imp(){ const P=S.imp?.p; const M=$('#main');
  if(!P){ M.innerHTML=`<div class="card"><div class="card-b" style="max-width:820px"><h1>Import from Vyapar</h1><p class="mut" style="margin:10px 0;line-height:1.7">Upload the reports exactly as Vyapar exports them (.xls) — or saved as .xlsx. You can upload all three together:</p><ul class="mut sm-t" style="line-height:1.9"><li><b>Cash Flow Report</b> — sales, Cash Acess, purchases (with its <i>Item Details</i> sheet), payments, deposits, withdrawals, adjustments.</li><li><b>Expense Transaction Report</b> — every expense with category, payment type, paid / unpaid.</li><li><b>Stock Detail Report</b> — item list and Vyapar's quantity-out totals.</li></ul><p class="mut sm-t">Safe to repeat every month: rows already imported are skipped, so you can upload a longer Vyapar export (e.g. full year) any time while you are switching over. Locked months are never changed.</p><div class="drop" style="margin-top:14px"><input type="file" id="imp-files" accept=".xls,.xlsx" multiple><p class="mut sm-t" style="margin-top:8px">Choose 1–3 files</p></div><div class="err-box" id="imp-err"></div></div></div>`; return; }
  const by=P.by_type; const o=S.imp.opt;
  M.innerHTML=`<div class="card"><div class="card-h"><h2>Review: ${S.imp.names.map(esc).join(', ')}</h2><button class="out sm" data-a="imp-reset">Choose other files</button></div><div class="card-b"><p class="sm-t mut">Found: ${P.kinds.map(esc).join(' · ')} · ${DT(P.from)} to ${DT(P.to)} · Vyapar report generated ${DT(P.generated)}</p>${P.warnings.map(w=>`<div class="note w">${esc(w)}</div>`).join('')}
  <div class="tw"><table><thead><tr><th>Type</th><th class="n">Rows</th><th class="n">New</th><th class="n">Bill total</th><th class="n">Paid / moved</th></tr></thead><tbody>${Object.entries(by).map(([k,v])=>`<tr><td>${badge(k)}</td><td class="n">${v.n}</td><td class="n"><b>${v.new}</b></td><td class="n">${R(v.total)}</td><td class="n">${R(v.paid)}</td></tr>`).join('')}<tr class="tot"><td>Total</td><td class="n">${P.total}</td><td class="n">${P.new}</td><td colspan="2" class="n">Cash effect ${R(P.cash_effect)}</td></tr></tbody></table></div>
  <p class="sm-t" style="margin-top:10px">${P.parties} parties (${P.new_parties.length} new) · ${P.items} items (${P.new_items.length} new) · ${P.stock_rows} stock rows ${P.locked?`· <b class="neg">${P.locked} rows in locked months will be skipped</b>`:''}</p>
  <label class="ck"><input type="checkbox" data-opt="cash_access" ${o.cash_access?'checked':''}> Book Vyapar “Cash Acess” sales as <b>Cash Acess (not a sale)</b> — recommended</label><label class="ck"><input type="checkbox" data-opt="owner_home" ${o.owner_home?'checked':''}> Treat money “withdrawn” from <b>Safik Home</b> as <b>Owner money in</b> — recommended</label></div></div>
  ${P.unmapped_categories.length?`<div class="card"><div class="card-h"><h2>New expense categories → group</h2><span class="mut sm-t">Groups drive the profit report.</span></div><div class="tw"><table><tbody>${P.unmapped_categories.map(c=>`<tr><td>${esc(c)}</td><td><select data-cg="${esc(c)}">${P.groups.map(g=>`<option ${S.imp.cg[c]===g?'selected':''}>${esc(g)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div></div>`:''}
  <div class="acts"><button class="pri" data-a="imp-confirm">Import ${P.new} new entries</button></div><div class="err-box" id="imp-err"></div>`; }
async function impLoad(){ const err=$('#imp-err'); try{ err.textContent='Reading files…'; const files=await Promise.all(S.imp.raw.map(f=>new Promise((ok,no)=>{ const r=new FileReader(); r.onload=()=>ok({name:f.name,data:String(r.result).split(',')[1]}); r.onerror=no; r.readAsDataURL(f); })));
  S.imp.files=files; S.imp.names=files.map(f=>f.name); S.imp.p=await api('import-preview',{files,options:S.imp.opt}); S.imp.p.unmapped_categories.forEach(c=>S.imp.cg[c]??=/salar|staff|wage|tip/i.test(c)?'Staff':'Office & misc'); imp(); }catch(e){ (err||{}).textContent=e.message; toast(e.message,true); } }

function showVerify(r){ const v=r.verify||{checks:[]};
  openModal(v.ok?'✓ Import verified':'⚠ Import finished — check below',`<div class="kpis">${kpi('New entries',r.created,'grn')}${kpi('Already there (skipped)',r.skipped)}${kpi('Item lines',r.lines)}${kpi('Updated',(r.updated||0)+(r.lines_repaired||0))}${kpi('Locked months skipped',r.locked,r.locked?'red':'')}</div>
  <div class="tw"><table><thead><tr><th>Check</th><th class="n">Vyapar</th><th class="n">Books</th><th></th></tr></thead><tbody>${v.checks.map(c=>`<tr><td style="white-space:normal">${esc(c[0])}</td><td class="n">${esc(c[1])}</td><td class="n">${c[2]===null?'':esc(c[2])}</td><td>${c[3]?'<span class="st Clear">OK</span>':'<span class="st Overpaid">Check</span>'}</td></tr>`).join('')}</tbody></table></div>
  ${v.missing&&v.missing.length?`<details class="more" open><summary>${v.missing.length} not imported</summary><ul>${v.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}
  <h3 style="margin:12px 0 6px">Vyapar rows by type</h3><div class="tw"><table><thead><tr><th>Vyapar type</th><th class="n">Rows</th><th class="n">Money in</th><th class="n">Money out</th></tr></thead><tbody>${Object.entries(v.by_type||{}).map(([k,x])=>`<tr><td>${esc(k)}</td><td class="n">${x.rows}</td><td class="n">${R(x.in)}</td><td class="n">${R(x.out)}</td></tr>`).join('')}</tbody></table></div>`,true); }
/* ---------- settings ---------- */
async function set(){ const cats=Object.entries(S.boot.categories).sort((a,b)=>a[1].localeCompare(b[1])||a[0].localeCompare(b[0]));
  $('#main').innerHTML=`<div class="grid2"><div class="card"><div class="card-b"><h2>Accounts & cash</h2><form data-form="settings"><label class="f" style="margin-top:12px">Payment accounts (comma separated; “Cash” is the drawer)<input name="accounts" value="${esc(S.boot.accounts.join(', '))}"></label><div class="fg"><label class="f">Opening cash on start date ₹<input name="opening_cash" value="${rup(S.boot.opening_cash)}"></label><label class="f">Warn when cash in hand above ₹<input name="cash_limit" value="${rup(S.boot.cash_limit)}"></label></div><h2 style="margin-top:16px">Expense categories</h2><p class="mut sm-t">Each category belongs to a group. “Old dues” and “Transfer” groups are kept out of profit.</p><div class="tw" style="max-height:50vh"><table><tbody>${cats.map(([c,g])=>`<tr><td><input data-cat value="${esc(c)}" style="width:100%;padding:6px;border:1px solid var(--line);border-radius:6px"></td><td><select data-catg>${S.boot.groups.map(x=>`<option ${x===g?'selected':''}>${esc(x)}</option>`).join('')}</select></td></tr>`).join('')}<tr><td><input data-cat placeholder="＋ new category" style="width:100%;padding:6px;border:1px solid var(--line);border-radius:6px"></td><td><select data-catg>${S.boot.groups.map(x=>`<option>${esc(x)}</option>`).join('')}</select></td></tr></tbody></table></div><div class="acts"><button class="pri">Save settings</button></div></form></div></div>
  <div class="card"><div class="card-b"><h2>Maintenance</h2><p class="mut sm-t" style="line-height:1.8;margin:8px 0 12px">Install updates for CRM, Salary and Books, see server health and table sizes, and download a backup first.</p><a href="upgrade.php"><button class="pri">Open Database upgrade</button></a><h2 style="margin-top:22px">Monthly routine</h2><ol class="sm-t" style="line-height:1.9;padding-left:18px"><li>Every day: Petpooja sale (split Cash/UPI/Card), Cash Acess, expenses, purchases with bill number.</li><li>Weekly: pay suppliers from <b>Parties & dues</b>; deposit extra cash.</li><li>Month end: stock count, Salary Register lock, check <b>Audit checks</b>, count cash and <b>lock the month</b>.</li></ol></div></div></div>`; }

/* ---------- entry dialog ---------- */
function lineRow(l={}){ return `<tr><td><input list="dl-items" data-l="item" value="${esc(l.item||'')}" placeholder="Item"></td><td><input data-l="qty" value="${l.qty??''}" inputmode="decimal" placeholder="Qty" style="width:70px"></td><td><input data-l="unit" value="${esc(l.unit||'')}" placeholder="Unit" style="width:60px"></td><td><input data-l="rate" value="${l.rate!=null?rup(l.rate):''}" inputmode="decimal" placeholder="Rate" style="width:80px"></td><td><input data-l="discount" value="${l.discount?rup(l.discount):''}" inputmode="decimal" placeholder="Disc ₹" style="width:70px"></td><td><input data-l="tax" value="${l.tax?rup(l.tax):''}" inputmode="decimal" placeholder="GST ₹" style="width:64px"></td><td><input data-l="amount" value="${l.amount!=null?rup(l.amount):''}" inputmode="decimal" placeholder="Amount" style="width:90px"></td><td class="x"><button type="button" class="sm dan" data-a="del-line">×</button></td></tr>`; }
async function entry(t={}){ if(!S.lists) await loadLists(); const type=t.type||'expense'; const T=S.boot.types; const L=S.lists; const isNew=!t.id;
  const f=v=>esc(v??''); const lines=(t.lines||[]).length?t.lines:(T[type].lines?[{}]:[]);
  openModal(isNew?'New entry':`${esc(T[type].label)} · ${DT(t.date)}`,`<form data-form="txn" data-id="${t.id||0}"><div class="types">${Object.entries(T).map(([k,v])=>`<button type="button" data-a="ttype" data-v="${k}" class="${k===type?'on':''}">${esc(v.label)}</button>`).join('')}</div><input type="hidden" name="type" value="${type}">
  <div class="fg"><label class="f">Date<input type="date" name="date" value="${f(t.date||S.boot.today)}" required></label>${T[type].dir!=='transfer'?`<label class="f">Party ${T[type].party?'*':'(optional)'}<input name="party" list="dl-parties" value="${f(t.party)}" ${T[type].party?'required':''}></label>`:''}${type==='expense'?`<label class="f">Category *<input name="category" list="dl-cats" value="${f(t.category)}" required></label>`:''}<label class="f">${type==='transfer'?'From account':'Account'}<select name="account">${L.accounts.map(a=>`<option ${a===(t.account||'Cash')?'selected':''}>${esc(a)}</option>`).join('')}</select></label>${type==='transfer'?`<label class="f">To account<select name="to_account">${L.accounts.map(a=>`<option ${a===(t.to_account||L.accounts[1])?'selected':''}>${esc(a)}</option>`).join('')}</select></label>`:''}${['purchase','sale'].includes(type)?`<label class="f">Bill / invoice no<input name="bill_no" value="${f(t.bill_no)}"></label>`:''}</div>
  ${T[type].lines?`<h3 style="margin-top:6px">Items</h3><table class="lines"><tbody id="lines">${lines.map(lineRow).join('')}</tbody></table><button type="button" class="sm out" data-a="add-line" style="margin-top:6px">＋ Item</button>`:''}
  <div class="fg">${['purchase','sale','expense'].includes(type)?`<label class="f">Bill total ₹<input name="total" id="e-total" value="${t.total!=null?rup(t.total):''}" inputmode="decimal" ${T[type].lines?'placeholder="auto from items"':''}></label><label class="f">${type==='sale'?'Received now':'Paid now'} ₹<input name="paid" id="e-paid" value="${t.paid!=null?rup(t.paid):''}" inputmode="decimal" placeholder="= total if blank"></label>`:`<label class="f">Amount ₹ *<input name="total" value="${t.total!=null?rup(t.total):''}" inputmode="decimal" required></label>`}</div>
  <label class="f">Note / reason${['add_cash','reduce_cash','owner_in','owner_draw'].includes(type)?' *':''}<input name="description" value="${f(t.description)}" maxlength="500"></label>
  <p class="mut sm-t" style="margin-top:6px">${({cash_access:'Petpooja “Cash Acess” / non-billing cash: adds to cash, never to sales.',purchase:'Unpaid part becomes the supplier\'s due. Pay later from Parties & dues.',sale:'Daily Petpooja sale: party “Petpooja Sale”. For B2B (bus operators) use their name; unpaid part becomes receivable.',transfer:'Cash deposited to bank, or withdrawn from bank to cash.',owner_in:'Money the owner brings from home — capital, not income.',payment_out:'Payment to a supplier against their dues. Staff salary/advance → use the Salary Register.'})[type]||''}</p>
  <div class="acts">${!isNew?`<button type="button" class="dan" data-a="void" data-id="${t.id}">Cancel entry</button>`:''}<button class="pri">${isNew?'Save':'Save changes'}</button></div></form>
  <datalist id="dl-parties">${L.parties.map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist><datalist id="dl-cats">${Object.keys(L.categories).map(c=>`<option value="${esc(c)}">`).join('')}</datalist><datalist id="dl-items">${L.items.map(i=>`<option value="${esc(i.name)}">`).join('')}</datalist>`,!!T[type].lines); S.cur=t; }
function sumLines(){ let s=0; $$('#lines tr').forEach(tr=>{ const a=+tr.querySelector('[data-l=amount]').value||0; s+=a; }); const tt=$('#e-total'); if(tt&&$$('#lines tr').length) tt.value=s?s.toFixed(2).replace(/\.00$/,''):''; }

const T_lines=(nt,c)=>S.boot.types[nt].lines?(c.lines||[]):[];
/* ---------- events ---------- */
async function reload(){ await refreshBoot(); render(); }
async function refreshBoot(){ const b=await api('boot'); S.boot=b; }
document.addEventListener('click',async ev=>{ const t=ev.target.closest('[data-a],[data-tab],[data-kind],[data-asv],[data-if]'); if(!t) return;
  try{ if(t.dataset.tab){ if(modal.open) modal.close(); S.tab=t.dataset.tab; return render(); }
    if(t.dataset.kind){ S.kind=t.dataset.kind; return par(); } if(t.dataset.asv){ S.asv=t.dataset.asv; return aud(); } if(t.dataset.if){ S.if=t.dataset.if; return stk(); }
    const a=t.dataset.a, id=+t.dataset.id;
    if(a==='close') return modal.close();
    if(a==='setup'){ await api('setup',{}); toast('Books ready'); return boot(); }
    if(a==='new') return entry({type:t.dataset.type||'expense'});
    if(a==='ttype'){ const c=S.cur||{}; const fd=Object.fromEntries(new FormData($('[data-form=txn]'))); return entry({...c,...fd,total:fd.total?Math.round(fd.total*100):null,paid:fd.paid?Math.round(fd.paid*100):null,type:t.dataset.v,id:c.id,lines:T_lines(t.dataset.v,c)}); }
    if(a==='edit'){ const x=await api('txn',undefined,'&id='+id); return entry(x); }
    if(a==='add-line'){ $('#lines').insertAdjacentHTML('beforeend',lineRow()); return; }
    if(a==='del-line'){ t.closest('tr').remove(); return sumLines(); }
    if(a==='void'){ const why=prompt('Why cancel this entry? (kept in the audit log)'); if(!why) return; await api('txn-void',{id,reason:why}); modal.close(); toast('Entry cancelled'); await loadLists(); return render(); }
    if(a==='stmt') return stmt(id);
    if(a==='pay-party'||a==='recv-party'){ if(!S.parties) S.parties=(await api('parties')).parties; const p=S.parties.find(x=>x.id===id); return entry({type:a==='pay-party'?'payment_out':'payment_in',party:p.name,total:a==='pay-party'?p.payable:p.receivable}); }
    if(a==='party-edit'){ if(!S.parties) S.parties=(await api('parties')).parties; return partyEdit(id); }
    if(a==='merge-party'){ if(!S.parties) S.parties=(await api('parties')).parties; return mergeDialog('party'); }
    if(a==='merge-item') return mergeDialog('item');
    if(a==='item') return itemCard(id); if(a==='item-edit') return itemEdit(id);
    if(a==='move') return moveDialog(t.dataset.k);
    if(a==='ecat'){ S.ec=t.dataset.c; return exp(); }
    if(a==='reclass'){ const ids=t.dataset.ids.split(',').filter(Boolean).map(Number); if(!confirm(`Change ${ids.length} entries to “Cash Acess (not a sale)”? Entries above ₹50,000 (like the 31/07 plug) are left for you to check one by one.`)) return; const r=await api('reclassify',{from:t.dataset.from,to:'cash_access',ids}); toast(r.changed+' entries changed'); return aud(); }
    if(a==='aall'){ S.aall=!S.aall; return aud(); }
    if(a==='imp-reset'){ S.imp=null; return imp(); }
    if(a==='imp-confirm'){ t.disabled=true; t.textContent='Importing…'; try{ const r=await api('import-confirm',{files:S.imp.files,options:{...S.imp.opt,category_groups:S.imp.cg}}); S.imp=null; await refreshBoot(); await loadLists(); S.month=S.boot.months[0]?.month||S.month; S.tab='dash'; render(); return showVerify(r); }catch(e){ $('#imp-err').textContent=e.message; t.disabled=false; t.textContent='Import'; return; } }
    if(a==='lock'){ const s=await api('month',undefined,'&m='+S.month); return openModal('Lock '+MON(S.month),`<form data-form="lock"><div class="calc"><div><span>Book cash on ${DT(s.to)}</span><b>${R(s.cash.closing)}</b></div></div><div class="fg"><label class="f">Cash actually counted ₹<input name="counted_cash" inputmode="decimal"></label></div><label class="f">Note<input name="note" placeholder="difference reason, who counted"></label><p class="mut sm-t">After locking, nobody can add/edit entries dated in this month (owner can unlock with a reason).</p><div class="acts"><button class="pri">Lock month</button></div></form>`); }
    if(a==='unlock'){ const why=prompt('Reason for unlocking (kept in audit log)'); if(!why) return; await api('month-unlock',{month:S.month,reason:why}); toast('Unlocked'); return reload(); }
    if(a==='day-csv'){ location.href=`books-api.php?r=export&what=daybook&from=${S.from||S.month+'-01'}&to=${S.to||lastDay(S.month)}&account=${encodeURIComponent(S.acct)}`; return; }
    if(a==='exp-csv'){ location.href='books-api.php?r=export&what=expenses&month='+S.month; return; }
    if(a==='parties-csv'){ location.href='books-api.php?r=export&what=parties'; return; }
    if(a==='stock-csv'){ location.href='books-api.php?r=export&what=stock'; return; }
  }catch(e){ if(modal.open) mErr(e.message); toast(e.message,true); } });
document.addEventListener('change',async ev=>{ const t=ev.target;
  if(t.id==='month-pick'){ S.month=t.value; S.from=S.to=null; return render(); }
  if(t.id==='d-from'){ S.from=t.value; return day(); } if(t.id==='d-to'){ S.to=t.value; return day(); } if(t.id==='d-acct'){ S.acct=t.value; return day(); } if(t.id==='d-type'){ S.tf=t.value; return day(); }
  if(t.id==='p-sup'){ S.pq=t.value; return pur(); }
  if(t.id==='imp-files'&&t.files.length){ S.imp={raw:[...t.files],opt:{cash_access:true,owner_home:true},cg:{}}; return impLoad(); }
  if(t.dataset.opt){ S.imp.opt[t.dataset.opt]=t.checked; return impLoad(); } if(t.dataset.cg){ S.imp.cg[t.dataset.cg]=t.value; return; }
  if(t.dataset.l==='item'){ const it=S.lists.items.find(i=>i.name.toLowerCase()===t.value.trim().toLowerCase()); if(it){ const tr=t.closest('tr'); if(!tr.querySelector('[data-l=unit]').value) tr.querySelector('[data-l=unit]').value=it.unit||''; if(!tr.querySelector('[data-l=rate]').value&&it.last_rate) tr.querySelector('[data-l=rate]').value=rup(it.last_rate); } } });
document.addEventListener('input',ev=>{ const t=ev.target;
  if(['qty','rate','discount','tax'].includes(t.dataset.l)){ const tr=t.closest('tr'); const g=k=>+tr.querySelector(`[data-l=${k}]`).value||0; const v=g('qty')*g('rate')-g('discount')+g('tax'); tr.querySelector('[data-l=amount]').value=g('qty')&&g('rate')?v.toFixed(2).replace(/\.00$/,''):''; sumLines(); }
  if(t.dataset.l==='amount') sumLines();
  if(t.id==='mv-q'){ const q=t.value.toLowerCase(); $$('[data-mv]').forEach(tr=>tr.style.display=tr.dataset.mv.includes(q)?'':'none'); }
  const deb=(k,fn)=>{ clearTimeout(S.qt); S.qt=setTimeout(()=>{ const pos=t.selectionStart; fn().then(()=>{ const e=$('#'+t.id); if(e){ e.focus(); e.setSelectionRange(pos,pos);} }); },300); };
  if(t.id==='d-q'){ S.q=t.value; deb('d',day); } if(t.id==='p-q'){ S.sq=t.value; deb('p',par); } if(t.id==='i-q'){ S.iq=t.value; deb('i',stk); } });
document.addEventListener('submit',async ev=>{ const f=ev.target.closest('[data-form]'); if(!f) return; ev.preventDefault(); const k=f.dataset.form; const b=Object.fromEntries(new FormData(f)); const btn=f.querySelector('button:not([type=button])'); if(btn) btn.disabled=true; mErr('');
  try{
    if(k==='txn'){ b.id=+f.dataset.id; b.lines=$$('#lines tr').map(tr=>Object.fromEntries([...tr.querySelectorAll('[data-l]')].map(i=>[i.dataset.l,i.value]))).filter(l=>l.item.trim()); if(!b.paid&&b.total!==undefined) b.paid=b.total;
      const r=await api('txn-save',b); modal.close(); toast('Saved'); await loadLists(); if(!S.boot.months.find(m=>m.month===r.txn.date.slice(0,7))) await refreshBoot(); return render(); }
    if(k==='party'){ await api('party-save',{...b,id:+f.dataset.id}); modal.close(); toast('Saved'); await loadLists(); return render(); }
    if(k==='item'){ await api('item-save',{...b,id:+f.dataset.id}); modal.close(); toast('Saved'); await loadLists(); return render(); }
    if(k==='merge'){ if(b.from===b.into) throw Error('Choose two different ones.'); if(!confirm('Merge? This cannot be undone.')) return; await api(f.dataset.kind==='party'?'party-merge':'item-merge',{from:+b.from,into:+b.into}); modal.close(); toast('Merged'); await loadLists(); return render(); }
    if(k==='move'){ const items=Object.entries(b).filter(([n,v])=>n.startsWith('q_')&&v.trim()!=='').map(([n,v])=>({item_id:+n.slice(2),qty:v})); const r=await api('move-save',{kind:b.kind,date:b.date,note:b.note,items}); modal.close(); toast(r.saved+' items saved'); return render(); }
    if(k==='lock'){ await api('month-lock',{month:S.month,...b}); modal.close(); toast('Month locked'); return reload(); }
    if(k==='settings'){ const names=$$('[data-cat]').map(i=>i.value.trim()), groups=$$('[data-catg]').map(s=>s.value); const categories={}; names.forEach((n,i)=>{ if(n) categories[n]=groups[i]; });
      await api('settings',{accounts:b.accounts.split(','),opening_cash:b.opening_cash,cash_limit:b.cash_limit,categories}); toast('Settings saved'); await loadLists(); return reload(); }
  }catch(e){ mErr(e.message); if(!modal.open) toast(e.message,true); }finally{ if(btn&&btn.isConnected) btn.disabled=false; } });
boot();
})();
